import * as React from "react";
import { Separator as BaseSeparator } from "@base-ui-components/react/separator";
import { cn } from "@/lib/utils";

// shadcn-style Separator on the Base UI primitive (it carries the right ARIA role).
export function Separator({ className, ...props }: React.ComponentProps<typeof BaseSeparator>) {
  return (
    <BaseSeparator
      className={cn("bg-border data-[orientation=vertical]:w-px data-[orientation=vertical]:self-stretch h-px w-full", className)}
      {...props}
    />
  );
}
